mapper.select:
SELECT setting_value
FROM policy_settings
WHERE code = #{code}

mapper.update:
UPDATE gallery_photos
SET sort_order = #{sortOrder}
WHERE photo_id = #{photoId}
  AND semester_label = #{semester}
  AND state IN ('normal', 'hidden')

UPDATE gallery_photos
SET semester_label = #{semesterLabel},
    user_id        = #{userId}
WHERE photo_id = #{photoId}
  AND state IN ('normal', 'hidden')

UPDATE gallery_photos
SET state = 'deleted'
WHERE photo_id = #{photoId}
  AND user_id = #{userId}
  AND state = 'normal'

UPDATE gallery_photos
SET title    = #{title},
    hashtags = #{hashtags}
WHERE photo_id = #{photoId}
  AND state IN ('normal', 'hidden')

UPDATE gallery_photos
SET state = #{to}
WHERE photo_id = #{photoId}
  AND state = #{from}
